// Spawned's handlers, in the order they run
static void tide_dispatch_Spawned(tide_world *tide_w, tide_entity tide_target, const Spawned *tide_event)
{
    tide_location tide_loc = {TIDE_ARCHETYPE_NONE, 0};
    const tide_table *const tide_guess = &tide_w->arch1_Main;
    if (tide_guess->count) {
        const tide_entity tide_first = *(const tide_entity *)tide_table_get(tide_guess, &tide_columns_arch1_Main, 0, 0);
        const uint32_t tide_row = tide_target.index - tide_first.index;
        if (tide_row < tide_guess->count && tide_entity_equal(
                *(const tide_entity *)tide_table_get(tide_guess, &tide_columns_arch1_Main, tide_row, 0), tide_target)) {
            tide_loc = (tide_location){1u, tide_row};
        }
    }
    if (tide_loc.archetype == TIDE_ARCHETYPE_NONE) tide_loc = tide_entity_location(&tide_w->entities, tide_target);
    if (!tide_entity_is_null(tide_target) && tide_loc.archetype == TIDE_ARCHETYPE_NONE) return; // Gone by its turn
    // Setup
    switch (tide_loc.archetype) {
    case 1: { // Main
        tide_table *tide_t = &tide_w->arch1_Main;
        const uint32_t tide_c = tide_loc.row >> 11;
        const uint32_t tide_i = tide_loc.row & 2047u;
        const tide_entity *tide_ent = tide_table_column(tide_t, &tide_columns_arch1_Main, tide_c, 0);
        (void)tide_ent;
        const tide_entity *tide_scn = tide_table_column(tide_t, &tide_columns_arch1_Main, tide_c, 1);
        (void)tide_scn;
        tide_handler_Setup(tide_w, tide_event, tide_ent[tide_i], tide_scn[tide_i]);
        break;
    }
    default: break;
    }
}

// Drop's handlers, in the order they run
static void tide_dispatch_Drop(tide_world *tide_w, tide_entity tide_target, const Drop *tide_event, const tide_player_id *tide_sender)
{
    const tide_location tide_loc = tide_entity_location(&tide_w->entities, tide_target);
    if (!tide_entity_is_null(tide_target) && tide_loc.archetype == TIDE_ARCHETYPE_NONE) return; // Gone by its turn
    // DropBall
    tide_handler_DropBall(tide_w, tide_event, tide_sender);
}

