            const uint32_t tide_n = tide_table_rows(tide_t, 11, tide_c);
            const uint32_t tide_from = (uint32_t)((uint64_t)tide_n * tide_piece / tide_pieces);
            const uint32_t tide_to = (uint32_t)((uint64_t)tide_n * (tide_piece + 1u) / tide_pieces);
            const tide_entity *tide_ent = tide_table_column(tide_t, &tide_columns_arch0_Ball_Health, tide_c, 0);
            const tide_entity *tide_scn = tide_table_column(tide_t, &tide_columns_arch0_Ball_Health, tide_c, 1);
