const uint8_t *tide_local_command(const tide_local *local, uint32_t channel, uint32_t *size)
{
    for (uint32_t i = 0; i < local->tide_outgoing_count; i++) {
        if (local->tide_outgoing[i].channel != channel) continue;
        if (size) *size = local->tide_outgoing[i].size;
        return local->tide_outgoing[i].data;
    }
    if (size) *size = 0;
    return NULL;
}

void tide_local_command_sent(tide_local *local, uint32_t channel)
{
    for (uint32_t i = 0; i < local->tide_outgoing_count; i++) {
        if (local->tide_outgoing[i].channel != channel) continue;
        free(local->tide_outgoing[i].data);
        memmove(local->tide_outgoing + i, local->tide_outgoing + i + 1u, (size_t)(--local->tide_outgoing_count - i) * sizeof *local->tide_outgoing);
        return;
    }
}

// Lets go of every command waiting: as the match goes, and before the local state's memory
static void tide_local_clear_outgoing(tide_local *local)
{
    for (uint32_t i = 0; i < local->tide_outgoing_count; i++) free(local->tide_outgoing[i].data);
    local->tide_outgoing_count = 0;
}

static bool tide_game_check_command(const uint8_t *data, uint32_t size, uint32_t *channel)
{
    if (!data || size < 10u || size > TIDE_COMMAND_BYTES) return false;
    const uint32_t mark = tide_scratch_mark();
    bool ok = false;
    tide_entity target;
    switch ((uint32_t)data[0] | ((uint32_t)data[1] << 8u)) {
    case 9: { Drop value; ok = tide_read_command_Drop(data, size, &target, &value); if (ok && channel) *channel = 0u; break; }
    case 10: { Poison value; ok = tide_read_command_Poison(data, size, &target, &value); if (ok && channel) *channel = 0u; break; }
    case 11: { Cure value; ok = tide_read_command_Cure(data, size, &target, &value); if (ok && channel) *channel = 0u; break; }
    default: break;
    }
    tide_scratch_reset(mark);
    return ok;
}

static uint32_t tide_game_command_sequence(const void *world, tide_player_id player, uint32_t channel)
{
    const tide_world *w = world;
    const int32_t index = tide_player_index(player);
    if (index < 0 || (uint32_t)index >= TIDE_GAME_PLAYERS) return 0;
    switch (channel) {
    case 0u:
        switch (index) {
        case 0: return (uint32_t)w->tide_command_state.seq0;
        default: return 0;
        }
    default: return 0;
    }
}

static void tide_game_keep_commands(void *to, const void *from)
{
    memcpy(&((tide_world *)to)->tide_command_state, &((const tide_world *)from)->tide_command_state,
           sizeof ((tide_world *)to)->tide_command_state);
}

static bool tide_game_command(void *world, tide_player_id sender, uint32_t channel, uint32_t sequence, const uint8_t *data, uint32_t size)
{
    tide_world *w = world;
    if (tide_player_index(sender) < 0 || (uint32_t)tide_player_index(sender) >= TIDE_GAME_PLAYERS) return false;
    uint32_t own = 0;
    if (!tide_game_check_command(data, size, &own) || own != channel) return false;
    const uint32_t was = tide_game_command_sequence(w, sender, channel);
    if (was == UINT32_MAX || sequence != was + 1u) return false;
    const uint32_t mark = tide_scratch_mark();
    tide_entity target;
    bool ok = false;
    switch ((uint32_t)data[0] | ((uint32_t)data[1] << 8u)) {
    case 9: {
        Drop value;
        if (!tide_read_command_Drop(data, size, &target, &value)) break;
        const Drop defaults = (Drop){0};
        (void)defaults;
        if (!tide_is_finite_f(value.at.x)) value.at.x = defaults.at.x;
        if (!tide_is_finite_f(value.at.y)) value.at.y = defaults.at.y;
        tide_command *c = tide_cmd_push(w, TIDE_CMD_EVENT, 9, target, TIDE_COMMAND_SIZE(event_Drop));
        c->sender = sender;
        c->data.event_Drop = value;
        ok = true;
        break;
    }
    case 10: {
        Poison value;
        if (!tide_read_command_Poison(data, size, &target, &value)) break;
        const Poison defaults = (Poison){0};
        (void)defaults;
        tide_command *c = tide_cmd_push(w, TIDE_CMD_EVENT, 10, target, TIDE_COMMAND_SIZE(event_Poison));
        c->sender = sender;
        c->data.event_Poison = value;
        ok = true;
        break;
    }
    case 11: {
        Cure value;
        if (!tide_read_command_Cure(data, size, &target, &value)) break;
        const Cure defaults = (Cure){0};
        (void)defaults;
        tide_command *c = tide_cmd_push(w, TIDE_CMD_EVENT, 11, target, TIDE_COMMAND_SIZE(event_Cure));
        c->sender = sender;
        c->data.event_Cure = value;
        ok = true;
        break;
    }
    default: break;
    }
    if (ok) {
        switch (channel) {
        case 0u:
            switch (tide_player_index(sender)) {
            case 0: memcpy(&w->tide_command_state.seq0, &sequence, sizeof sequence); break;
            default: break;
            }
            break;
        default: break;
        }
    }
    tide_scratch_reset(mark);
    return ok;
}

bool tide_local_take_request(tide_local *local, tide_session_request *request, tide_start *start)
{
    if (local->tide_request.kind != TIDE_REQUEST_NONE) {
        *request = local->tide_request;
        *start = local->tide_request_start;
        local->tide_request = (tide_session_request){0};
        local->tide_request_start = (tide_start){0};
        return true;
    }
    if (local->tide_request_open.kind != TIDE_REQUEST_NONE) {
        *request = local->tide_request_open;
        local->tide_request_open = (tide_session_request){0};
        return true;
    }
    if (local->tide_request_watch.kind != TIDE_REQUEST_NONE) {
        *request = local->tide_request_watch;
        local->tide_request_watch = (tide_session_request){0};
        return true;
    }
    if (local->tide_kick_count == 0) {
        if (local->tide_copy.kind == TIDE_REQUEST_NONE) return false;
        *request = local->tide_copy;
        local->tide_copy = (tide_session_request){0};
        return true;
    }
    *request = local->tide_kicks[0];
    local->tide_kick_count--;
    memmove(local->tide_kicks, local->tide_kicks + 1, local->tide_kick_count * sizeof local->tide_kicks[0]);
    memset(&local->tide_kicks[local->tide_kick_count], 0, sizeof local->tide_kicks[0]);
    return true;
}

void tide_local_set_session(tide_local *local, uint32_t state, tide_player_id player, uint32_t ping, bool server,
                            bool open, const char *room)
{
    local->Session.state = (int32_t)state;
    local->Session.player = player;
    local->Session.ping = (int32_t)ping;
    local->Session.server = server;
    local->Session.open = open;
    size_t n = room ? strlen(room) : 0u;
    if (n >= sizeof local->tide_room) n = sizeof local->tide_room - 1u;
    memcpy(local->tide_room, room ? room : "", n);
    memset(local->tide_room + n, 0, sizeof local->tide_room - n);
    tide_local_set_invite(local, local->tide_room);
}

void tide_local_set_invite(tide_local *local, const char *invite)
{
    size_t n = 0u;
    while (invite && n < sizeof local->tide_invite && (unsigned char)invite[n] >= 0x20u
           && (unsigned char)invite[n] <= 0x7Eu) n++;
    if (!invite || n == sizeof local->tide_invite || invite[n]) n = 0u;
    memmove(local->tide_invite, n ? invite : "", n);
    memset(local->tide_invite + n, 0, sizeof local->tide_invite - n);
}

void tide_local_connected(tide_local *local)
{
    tide_cmd_send_Connected(local, (tide_entity){0}, (Connected){0});
}

void tide_local_disconnected(tide_local *local, uint32_t reason, const char *message)
{
    tide_local_clear_outgoing(local);
    size_t n = message ? strlen(message) : 0u;
    if (n >= sizeof local->tide_message) n = sizeof local->tide_message - 1u;
    memcpy(local->tide_message, message ? message : "", n);
    memset(local->tide_message + n, 0, sizeof local->tide_message - n);
    tide_cmd_send_Disconnected(local, (tide_entity){0}, (Disconnected){.reason = (int32_t)reason});
}

