static uint64_t tide_game_hash_on(const void *world, const tide_jobs *jobs)
{
    const tide_world *w = world;
    tide_stale_pages stale = {0};
    tide_entities_stale(&w->entities, &stale);
    tide_table_stale(&w->arch0_Ball_Health, &tide_columns_arch0_Ball_Health, &stale);
    tide_table_stale(&w->arch1_Main, &tide_columns_arch1_Main, &stale);
    tide_pages_hash(&stale, jobs);
    return tide_world_hash(w);
}

